public function upload(UploadedFile $file): string
{
    // Never trust the client name: basename + free-name reservation.
    $wanted = basename($file->getClientOriginalName());
    $name = $this->resolver->reserveFreeName(
        $this->storage, $wanted);
    $file->move($this->storage, $name);
    return $name;
}

